code = r'''
import torch, json
LM = W('lm_head.weight')  # [V, d]
NW = W('model.norm.weight')
def tokids(words):
    ids=[]
    for w in words:
        for v in [w, ' '+w]:
            e=encode(v)
            if len(e)==1: ids.append(e[0])
    return sorted(set(ids))
def group_dir(words):
    ids=tokids(words)
    U=LM[ids]
    d=U.mean(0)-LM.mean(0)
    return d/d.norm(), ids
def top_units(layer, d, k=64, sign=1):
    D=W(f'model.layers.{layer}.mlp.down_proj.weight')  # [d, ff]
    Dn = D*NW[:,None]
    cos = (d@Dn)/(Dn.norm(dim=0)+1e-6)
    v,i = torch.topk(sign*cos, k)
    return i.tolist(), v.tolist()
def logit_lens(vec, k=12):
    l = LM @ (vec*NW)
    t=torch.topk(l,k).indices.tolist(); b=torch.topk(-l,k).indices.tolist()
    return [decode([x]) for x in t],[decode([x]) for x in b]
'''
